          "answer": "① 환경과 일과를 일정하게 유지하도록 교육한다 — 매일 같은 시간에 식사·목욕·취침을 하고 가구 배치와 물건 위치를 바꾸지 않으며 시계·달력·가족사진으로 지남력을 돕는다. ② 의사소통 방법을 교육한다 — 정면에서 눈을 맞추고 저음으로 천천히 짧게 말하며 한 번에 한 가지만 지시하고, 예/아니오로 답할 수 있게 묻고 틀린 말을 지적하거나 논쟁하지 않고 감정을 먼저 수용한다. ③ 안전 관리를 교육한다 — 가스밸브 잠금장치, 문·창문 잠금, 욕실 미끄럼방지 매트와 안전손잡이, 칼·약·세제 보관, 실종에 대비한 인식표(배회감지기·지문 사전등록)를 준비한다. ④ 행동심리증상 대처를 교육한다 — 배회·초조는 통증·배고픔·요의·소음·피로 등 유발 요인을 먼저 찾아 제거하고 강제로 제지하기보다 관심을 다른 활동으로 돌리며, 석양증후군에는 오후에 조명을 밝히고 자극을 줄인다. ⑤ 일상생활 지원 원칙을 교육한다 — 남아 있는 능력은 스스로 하게 하고 필요한 부분만 돕는다(단추 대신 벨크로 옷, 한 벌씩 순서대로 꺼내주기). 무조건 대신해 주면 기능 저하가 빨라진다. ⑥ 영양·수분·배설 관리를 교육한다 — 소량씩 자주 제공하고 삼킴 상태를 관찰하며 정해진 시간에 화장실을 안내하고 체중을 정기적으로 측정한다(3개월 4kg 감소는 평가가 필요하다). ⑦ 투약 관리를 교육한다 — 약을 임의로 중단하지 말고 요일별 약상자로 관리하며 오심·구토·서맥·어지럼 등 부작용이 나타나면 보고하도록 한다. ⑧ 갑작스러운 변화는 섬망 신호임을 교육한다 — 며칠 사이 갑자기 멍해지거나 처지고 밤에 심해지며 헛것을 보거나 식사·수분 섭취를 못 하면 \"치매가 나빠진 것\"으로 넘기지 말고 즉시 진료를 받도록 한다. ⑨ 돌봄제공자 자신을 돌보도록 교육한다 — 노인장기요양보험 등급 재신청, 단기보호·방문요양, 치매안심센터 등록과 가족 자조모임을 안내하고 돌봄 부담·우울을 정기적으로 점검한다.",
