      "scenario": "76세 남성. 오늘 아침 8시경 신문을 보다가 갑자기 오른쪽 팔다리에 힘이 빠지고 말이 어눌해져 9시 40분 응급실에 도착하였다. 마지막으로 정상이었던 시각은 오전 7시 50분이다. 과거력: (1) 고혈압 15년, (2) 2형 당뇨 10년, (3) 이상지질혈증(LDL 콜레스테롤 158mg/dL), (4) 심방세동 — 항응고제를 자주 거르고 있었음, (5) 40년간 하루 1갑 흡연, 주 4회 소주 반 병 음주, (6) 아버지가 뇌졸중으로 사망한 가족력, (7) 3개월 전 잠깐 팔에 힘이 빠졌다가 30분 만에 회복된 적이 있음. 활력징후: 혈압 178/98mmHg, 맥박 112회/분(불규칙), 호흡 20회/분, 체온 36.8℃, SpO2 96%. 신경학적 사정: 의식 GCS 14점(눈뜸 4·언어 4·운동 6), 우측 상하지 도수근력 2/5, 우측 안면 하부 마비로 입꼬리 처짐, 구음장애, 물을 삼킬 때 사레가 들리고 목소리가 젖음. NIHSS 12점. Lab: 혈당 168mg/dL, 프로트롬빈시간(PT)/INR 1.1, 전혈구계산 정상.",
