          "answer": "우선 비약물 중재(수분·섬유질·활동·배변습관)를 충분히 시도하고, 효과가 없을 때 팽창성 → 삼투성 → 자극성 순으로 단계적으로 사용한다는 원칙을 지킨다. ① 팽창성 완하제(차전자피, 메틸셀룰로오스) — 수분을 흡수해 변의 부피를 늘려 자연스러운 연동운동을 유도하는 가장 생리적인 1차 약물이나, 반드시 충분한 물과 함께 복용해야 하며 물을 적게 마시거나 와상·장폐색 위험이 있는 노인에게는 오히려 막힐 수 있어 피한다. 효과는 2~3일 후 나타난다. ② 삼투성 완하제(락툴로오스, 폴리에틸렌글리콜(PEG), 산화마그네슘) — 장으로 수분을 끌어와 변을 무르게 하며 노인 만성 변비의 장기 사용에 비교적 안전하다. 락툴로오스는 복부 팽만·방귀가, 마그네슘 제제는 신기능이 저하된 노인에서 고마그네슘혈증(기면·서맥·저혈압)이 나타날 수 있어 주의한다. ③ 대변 연화제(docusate) — 변에 수분과 지방이 스며들게 해 부드럽게 만들며, 효과가 약해 단독으로는 부족하지만 배변 시 힘주기를 피해야 하는 심질환·치질 대상자에게 보조적으로 사용한다. ④ 자극성 완하제(bisacodyl, senna) — 장 점막을 직접 자극해 연동운동을 일으키며 효과가 빠르지만(경구 6~12시간, 좌약 15~60분) 복통·전해질 소실이 있고 장기 남용 시 장이 무력해지므로 단기간·간헐적으로만 사용한다. ⑤ 좌약과 관장 — 글리세린 좌약은 직장을 자극하고 윤활하며, 관장은 좌측 심스위에서 시행하되 노인은 장 천공과 전해질 이상 위험이 있어 비눗물 관장과 반복 관장을 피한다. 분변매복이 확인되면 관장·완하제보다 먼저 손가락으로 변을 부수어 제거하는 처치가 필요하다. ⑥ 마약성 진통제를 시작할 때는 변비에 내성이 생기지 않으므로 처음부터 완하제를 함께 처방해 예방하고, 항콜린제·1세대 항히스타민·철분제·칼슘통로차단제 등 변비 유발 약물을 재검토한다. ⑦ metoclopramide는 도파민을 차단하여 파킨슨병을 악화시키고 추체외로증상을 일으키므로 이 대상자에게는 피해야 하며, Beers Criteria상 노인에서 12주를 넘겨 사용하지 않는다.",
