          "answer": "① 불규칙한 식사와 식사량 부족 — 식욕이 없어 저녁을 자주 거르는데 약은 그대로 복용하여 새벽에 저혈당이 온다. 노인은 식욕부진·치아 문제·연하곤란으로 섭취가 들쭉날쭉하다. ② 설폰요소제(glimepiride)와 인슐린 사용 — 저혈당을 일으키는 대표 약물이며, 작용시간이 긴 설폰요소제는 Beers Criteria상 노인 회피 대상이다. ③ 신기능 저하 — 추정 사구체여과율 48mL/분/1.73㎡, 크레아티닌 1.4mg/dL로 인슐린과 경구약의 배설이 지연되어 약효가 오래 남아 저혈당이 길어진다. ④ 저혈당 무감지증 — 노화와 자율신경병증으로 발한·떨림·심계항진 같은 경고 증상이 사라져, 이 대상자처럼 식은땀 없이 갑자기 멍해지고 힘이 빠지는 혼돈·기면·낙상으로만 나타난다. ⑤ 다약제 복용과 지나치게 엄격한 혈당 목표 — 당화혈색소 6.8%, 공복혈당 82mg/dL는 복합이환 노인에게는 오히려 낮아 저혈당 위험이 크며(허약·복합이환 노인의 목표는 8.0~8.5%), 병용 약물이 증상을 가릴 수 있다. ⑥ 인지·시력 저하 — 백내장으로 약병 글씨를 읽기 어려워 약을 중복 복용하거나 식사 후 복용을 잊는 자가관리 오류가 생긴다. ⑦ 음주 — 공복 음주는 간의 포도당 생성을 억제해 심한 지연성 저혈당을 유발한다. 노인 당뇨의 핵심 원칙은 고혈당보다 저혈당이 더 위험하다는 것으로, 저혈당 1회가 낙상·골절·심근경색·인지저하로 이어진다.",
