          "answer": "① metformin(비구아나이드계) — 간의 포도당 생성을 억제하고 인슐린 감수성을 높이는 1차 약물로 단독으로는 저혈당을 거의 일으키지 않는다. 오심·설사·금속 맛이 흔해 식사 직후 저용량으로 시작하며, 드물지만 치명적인 유산증(근육통·과호흡·저체온·의식저하)을 관찰한다. ② metformin의 금기와 중단 — eGFR 30mL/분/1.73㎡ 미만이면 금기이며 현재 42로 신기능 감시가 필요하다. 요오드 조영제를 쓰는 검사에서는 검사 당일부터 중단하고 48시간 후 신기능을 확인한 뒤 재개하며, 장기 복용 시 비타민B12 결핍(빈혈·신경병증)을 확인한다. ③ 설폰요소제(glimepiride) — 췌장 베타세포에서 인슐린 분비를 자극하며 저혈당과 체중 증가가 대표 부작용이다. 식사 30분 전에 복용하되 식사를 거르면 복용하지 않도록 교육하고, 작용시간이 긴 glibenclamide·chlorpropamide는 Beers Criteria상 노인 회피 대상이다. ④ 노인에게 우선하는 약물 — 저혈당 위험이 낮은 DPP-4 억제제(sitagliptin, linagliptin)는 신기능에 따라 용량을 조정하며(linagliptin은 조정 불필요) 노인에게 비교적 안전하고, SGLT2 억제제는 심부전·만성신질환 예후를 개선하지만 요로감염·생식기 진균감염, 탈수와 기립성 저혈압, 정상혈당 케톤산증이 있어 수분 섭취와 회음부 위생을 교육하고 금식·수술 전에는 중단한다. ⑤ 인슐린을 시작하는 경우 — 초속효성(식사 직전), 속효성(30분 전), 중간형(NPH, 굴려서 섞음), 지속형(다른 인슐린과 섞지 않음)의 작용시간을 구분하고, 복부·상완·대퇴·둔부에 피하주사하되 같은 부위 안에서 2~3cm씩 옮겨 지방위축을 예방하며, 개봉 전은 냉장(2~8℃)·사용 중은 실온 4주 보관하고 주사 부위를 문지르거나 주사 직후 운동하지 않도록 교육한다. ⑥ 병용 약물 주의 — 베타차단제는 저혈당 경고 증상을 가리고, 스테로이드·thiazide 이뇨제는 혈당을 올리며, 공복 음주는 심한 지연성 저혈당을 유발한다. ⑦ 노인 맞춤 원칙 — 저혈당 위험이 낮은 약을 우선하고 목표 당화혈색소를 계층화해 완화하며, 신기능 변화에 따라 용량을 재조정하고 인지·시력·손 기능을 고려해 1일 복용 횟수를 최소화하며 복약순응도를 정기적으로 확인한다.",
