          "answer": "【발관리 교육】 ① 매일 밝은 곳에서 발등·발바닥·발가락 사이·발뒤꿈치를 살펴 상처·물집·발적·부종·색 변화·냄새를 찾고, 허리를 굽히기 어렵거나 시력이 나쁘면 거울을 쓰거나 요양보호사·가족에게 확인을 부탁하도록 교육한다. ② 발은 매일 미지근한 물(37℃ 이하)로 5분 이내 씻되, 감각이 둔하므로 물 온도는 반드시 손목·팔꿈치나 온도계로 확인하고 오래 담그지 않는다. ③ 씻은 뒤 발가락 사이까지 부드러운 수건으로 두드려 완전히 말리고(문지르지 않는다) 건조한 부위에만 보습제를 바르되 발가락 사이에는 바르지 않는다(짓무름·무좀 예방). ④ 발톱은 목욕 후 부드러울 때 일자로 자르고 모서리를 깊이 파지 않으며, 두껍거나 시력이 나쁘면 스스로 자르지 말고 도움을 받는다. ⑤ 티눈·굳은살·물집은 스스로 칼이나 가위로 제거하거나 티눈고·소독약을 붙이지 말고 반드시 의료진에게 보이도록 교육한다. ⑥ 실내에서도 맨발로 다니지 않고 앞이 막힌 편한 신발과 면양말을 신으며, 신기 전 신발 안을 손으로 훑어 이물질을 확인하고 새 신발은 하루 1~2시간부터 늘려 길들인다. ⑦ 전기장판·핫팩·뜨거운 물주머니·난로에 발을 직접 대지 않도록 교육한다 — 감각이 없어 화상을 입고도 모른 채 궤양으로 진행한다. ⑧ 금연하고, 작은 상처라도 2~3일 내 낫지 않으면 즉시 병원에 오도록 교육한다. 【저혈당 대처】 저혈당은 혈당 70mg/dL 미만이며 식은땀·손떨림·두근거림·심한 공복감·창백·어지럼이 나타나고 진행하면 어눌한 말·혼돈·경련·의식소실로 이어지는데, 노인은 이런 전형적 증상 없이 갑자기 멍해지거나 넘어지는 것으로만 나타나므로 평소와 다르면 먼저 혈당을 재도록 한다. 의식이 있으면 즉시 속효성 탄수화물 15g(주스나 콜라 1/2컵, 사탕 3~4개, 각설탕 3개, 설탕 1큰술)을 먹고 15분 뒤 다시 재어 여전히 70mg/dL 미만이면 같은 양을 반복하며(15-15 규칙), 회복 후 다음 식사까지 1시간 이상 남았으면 우유·크래커 등 복합탄수화물 간식을 먹는다. 초콜릿·아이스크림처럼 지방이 많은 음식은 흡수가 느려 부적절하다. 의식이 없거나 삼키지 못하면 절대 입에 아무것도 넣지 말고(흡인 위험) 고개를 옆으로 돌려 눕힌 뒤 처방된 글루카곤을 주사하고 즉시 119에 연락하도록 가족·요양보호사에게 시범 교육한다. 예방을 위해 식사와 약 복용 시간을 지키고 외출 시 사탕을 휴대하며 공복 음주를 피하고 당뇨 인식표를 지니게 한다.",
